 FOR r IN SELECT * FROM jsonb_to_recordset($data_v51$[{"course":"elixir","ordinal":1,"title":"Pattern Matching","theory":"Mit = prüft Elixir, ob ein Wert zu einem Muster passt. Eine unpassende Bindung löst einen MatchError aus.","example":"{:ok,wert}={:ok,3}","example_note":"wert erhält 3, weil die Tupelform passt.","task":"Entpacke ein erfolgreiches Tupel.","q1":{"question":"Welche Aussage erklärt „Pattern Matching“ richtig?","options":["Elixir-Daten sind unveränderlich. Eine erneute Bindung mit demselben Namen erzeugt einen neuen Bezug auf einen Wert.","Mit = prüft Elixir, ob ein Wert zu einem Muster passt. Eine unpassende Bindung löst einen MatchError aus.","Listen sind in Elixir einfach verkettete Folgen. Vorne anzufügen ist günstig, der Zugriff per Index nicht."],"correct":1,"explanation":"Mit = prüft Elixir, ob ein Wert zu einem Muster passt. Eine unpassende Bindung löst einen MatchError aus."},"q2":{"question":"Was zeigt das Beispiel zu „Pattern Matching“?","options":["Nach der zweiten Bindung ist x gleich 4, ohne den ursprünglichen Integer zu verändern.","neu enthält 0,1,2 und die ursprüngliche Liste bleibt unverändert.","wert erhält 3, weil die Tupelform passt."],"correct":2,"explanation":"wert erhält 3, weil die Tupelform passt."}},{"course":"elixir","ordinal":2,"title":"Unveränderliche Werte","theory":"Elixir-Daten sind unveränderlich. Eine erneute Bindung mit demselben Namen erzeugt einen neuen Bezug auf einen Wert.","example":"x=3\nx=x+1","example_note":"Nach der zweiten Bindung ist x gleich 4, ohne den ursprünglichen Integer zu verändern.","task":"Verändere einen Zähler durch Neuzuweisung.","q1":{"question":"Welche Aussage erklärt „Unveränderliche Werte“ richtig?","options":["Tupel enthalten eine feste Anzahl von Elementen und eignen sich häufig für Rückgaben mit Statuskennzeichen.","Maps enthalten Schlüssel und Werte. Atom-Schlüssel lassen sich oft mit Punktnotation lesen.","Elixir-Daten sind unveränderlich. Eine erneute Bindung mit demselben Namen erzeugt einen neuen Bezug auf einen Wert."],"correct":2,"explanation":"Elixir-Daten sind unveränderlich. Eine erneute Bindung mit demselben Namen erzeugt einen neuen Bezug auf einen Wert."},"q2":{"question":"Was zeigt das Beispiel zu „Unveränderliche Werte“?","options":["Nach der zweiten Bindung ist x gleich 4, ohne den ursprünglichen Integer zu verändern.","Das erste Element signalisiert Erfolg, das zweite enthält den Wert.","nutzer.name liefert Alex."],"correct":0,"explanation":"Nach der zweiten Bindung ist x gleich 4, ohne den ursprünglichen Integer zu verändern."}},{"course":"elixir","ordinal":3,"title":"Tupel","theory":"Tupel enthalten eine feste Anzahl von Elementen und eignen sich häufig für Rückgaben mit Statuskennzeichen.","example":"antwort={:ok,\"fertig\"}","example_note":"Das erste Element signalisiert Erfolg, das zweite enthält den Wert.","task":"Entwirf eine Fehlerantwort als Tupel.","q1":{"question":"Welche Aussage erklärt „Tupel“ richtig?","options":["Tupel enthalten eine feste Anzahl von Elementen und eignen sich häufig für Rückgaben mit Statuskennzeichen.","Listen sind in Elixir einfach verkettete Folgen. Vorne anzufügen ist günstig, der Zugriff per Index nicht.","|> übergibt das vorherige Ergebnis als erstes Argument an die nächste Funktion."],"correct":0,"explanation":"Tupel enthalten eine feste Anzahl von Elementen und eignen sich häufig für Rückgaben mit Statuskennzeichen."},"q2":{"question":"Was zeigt das Beispiel zu „Tupel“?","options":["neu enthält 0,1,2 und die ursprüngliche Liste bleibt unverändert.","Das erste Element signalisiert Erfolg, das zweite enthält den Wert.","Die Zahlen werden verdoppelt und anschließend summiert; das Ergebnis ist 12."],"correct":1,"explanation":"Das erste Element signalisiert Erfolg, das zweite enthält den Wert."}},{"course":"elixir","ordinal":4,"title":"Listen","theory":"Listen sind in Elixir einfach verkettete Folgen. Vorne anzufügen ist günstig, der Zugriff per Index nicht.","example":"liste=[1,2]\nneu=[0|liste]","example_note":"neu enthält 0,1,2 und die ursprüngliche Liste bleibt unverändert.","task":"Füge ein Element am Listenanfang ein.","q1":{"question":"Welche Aussage erklärt „Listen“ richtig?","options":["Maps enthalten Schlüssel und Werte. Atom-Schlüssel lassen sich oft mit Punktnotation lesen.","Listen sind in Elixir einfach verkettete Folgen. Vorne anzufügen ist günstig, der Zugriff per Index nicht.","Enum.filter wählt aus einem Enumerable die Elemente aus, die ein Prädikat erfüllen."],"correct":1,"explanation":"Listen sind in Elixir einfach verkettete Folgen. Vorne anzufügen ist günstig, der Zugriff per Index nicht."},"q2":{"question":"Was zeigt das Beispiel zu „Listen“?","options":["nutzer.name liefert Alex.","Nur die Werte 2 und 3 bleiben erhalten.","neu enthält 0,1,2 und die ursprüngliche Liste bleibt unverändert."],"correct":2,"explanation":"neu enthält 0,1,2 und die ursprüngliche Liste bleibt unverändert."}},{"course":"elixir","ordinal":5,"title":"Maps","theory":"Maps enthalten Schlüssel und Werte. Atom-Schlüssel lassen sich oft mit Punktnotation lesen.","example":"nutzer=%{name:\"Alex\",level:3}","example_note":"nutzer.name liefert Alex.","task":"Erstelle eine Map mit drei Feldern.","q1":{"question":"Welche Aussage erklärt „Maps“ richtig?","options":["|> übergibt das vorherige Ergebnis als erstes Argument an die nächste Funktion.","Enum.reduce verarbeitet eine Sammlung zu einem Akkumulatorwert.","Maps enthalten Schlüssel und Werte. Atom-Schlüssel lassen sich oft mit Punktnotation lesen."],"correct":2,"explanation":"Maps enthalten Schlüssel und Werte. Atom-Schlüssel lassen sich oft mit Punktnotation lesen."},"q2":{"question":"Was zeigt das Beispiel zu „Maps“?","options":["nutzer.name liefert Alex.","Die Zahlen werden verdoppelt und anschließend summiert; das Ergebnis ist 12.","Die Werte werden zu 6 addiert."],"correct":0,"explanation":"nutzer.name liefert Alex."}},{"course":"elixir","ordinal":6,"title":"Pipe Operator","theory":"|> übergibt das vorherige Ergebnis als erstes Argument an die nächste Funktion.","example":"[1,2,3] |> Enum.map(&(&1*2)) |> Enum.sum()","example_note":"Die Zahlen werden verdoppelt und anschließend summiert; das Ergebnis ist 12.","task":"Verknüpfe zwei Verarbeitungsschritte.","q1":{"question":"Welche Aussage erklärt „Pipe Operator“ richtig?","options":["|> übergibt das vorherige Ergebnis als erstes Argument an die nächste Funktion.","Enum.filter wählt aus einem Enumerable die Elemente aus, die ein Prädikat erfüllen.","Ein Guard schränkt Funktionsklauseln durch erlaubte Prüfungen ein."],"correct":0,"explanation":"|> übergibt das vorherige Ergebnis als erstes Argument an die nächste Funktion."},"q2":{"question":"Was zeigt das Beispiel zu „Pipe Operator“?","options":["Nur die Werte 2 und 3 bleiben erhalten.","Die Zahlen werden verdoppelt und anschließend summiert; das Ergebnis ist 12.","Nur ganze Zahlen passen zu dieser Klausel."],"correct":1,"explanation":"Die Zahlen werden verdoppelt und anschließend summiert; das Ergebnis ist 12."}},{"course":"elixir","ordinal":7,"title":"Enum.filter","theory":"Enum.filter wählt aus einem Enumerable die Elemente aus, die ein Prädikat erfüllen.","example":"Enum.filter([1,2,3],fn x->x>1 end)","example_note":"Nur die Werte 2 und 3 bleiben erhalten.","task":"Filtere Zahlen unter einer Grenze.","q1":{"question":"Welche Aussage erklärt „Enum.filter“ richtig?","options":["Enum.reduce verarbeitet eine Sammlung zu einem Akkumulatorwert.","Enum.filter wählt aus einem Enumerable die Elemente aus, die ein Prädikat erfüllen.","Eine rekursive Elixir-Funktion ruft sich auf einem kleineren Problem erneut auf und braucht einen Basisfall."],"correct":1,"explanation":"Enum.filter wählt aus einem Enumerable die Elemente aus, die ein Prädikat erfüllen."},"q2":{"question":"Was zeigt das Beispiel zu „Enum.filter“?","options":["Die Werte werden zu 6 addiert.","Die Liste wird elementweise bis zum leeren Fall abgebaut.","Nur die Werte 2 und 3 bleiben erhalten."],"correct":2,"explanation":"Nur die Werte 2 und 3 bleiben erhalten."}},{"course":"elixir","ordinal":8,"title":"Enum.reduce","theory":"Enum.reduce verarbeitet eine Sammlung zu einem Akkumulatorwert.","example":"Enum.reduce([1,2,3],0,fn x,sum->sum+x end)","example_note":"Die Werte werden zu 6 addiert.","task":"Summiere vier Preise.","q1":{"question":"Welche Aussage erklärt „Enum.reduce“ richtig?","options":["Ein Guard schränkt Funktionsklauseln durch erlaubte Prüfungen ein.","GenServer ist ein OTP-Baustein für zustandsbehaftete Serverprozesse mit Nachrichtenbehandlung.","Enum.reduce verarbeitet eine Sammlung zu einem Akkumulatorwert."],"correct":2,"explanation":"Enum.reduce verarbeitet eine Sammlung zu einem Akkumulatorwert."},"q2":{"question":"Was zeigt das Beispiel zu „Enum.reduce“?","options":["Die Werte werden zu 6 addiert.","Nur ganze Zahlen passen zu dieser Klausel.","Das Modul kann danach passende Callback-Funktionen implementieren."],"correct":0,"explanation":"Die Werte werden zu 6 addiert."}},{"course":"elixir","ordinal":9,"title":"Funktionen mit Guards","theory":"Ein Guard schränkt Funktionsklauseln durch erlaubte Prüfungen ein.","example":"def status(n) when is_integer(n), do: :ok","example_note":"Nur ganze Zahlen passen zu dieser Klausel.","task":"Verwende einen Guard für nichtnegative Zahlen.","q1":{"question":"Welche Aussage erklärt „Funktionen mit Guards“ richtig?","options":["Ein Guard schränkt Funktionsklauseln durch erlaubte Prüfungen ein.","Eine rekursive Elixir-Funktion ruft sich auf einem kleineren Problem erneut auf und braucht einen Basisfall.","ExUnit stellt Testfälle und Assertions für Elixir bereit."],"correct":0,"explanation":"Ein Guard schränkt Funktionsklauseln durch erlaubte Prüfungen ein."},"q2":{"question":"Was zeigt das Beispiel zu „Funktionen mit Guards“?","options":["Die Liste wird elementweise bis zum leeren Fall abgebaut.","Nur ganze Zahlen passen zu dieser Klausel.","Der Test meldet Abweichungen beim erwarteten Ergebnis."],"correct":1,"explanation":"Nur ganze Zahlen passen zu dieser Klausel."}},{"course":"elixir","ordinal":10,"title":"Rekursion","theory":"Eine rekursive Elixir-Funktion ruft sich auf einem kleineren Problem erneut auf und braucht einen Basisfall.","example":"def laenge([]),do:0\ndef laenge([_|rest]),do:1+laenge(rest)","example_note":"Die Liste wird elementweise bis zum leeren Fall abgebaut.","task":"Erstelle eine einfache rekursive Summenfunktion.","q1":{"question":"Welche Aussage erklärt „Rekursion“ richtig?","options":["GenServer ist ein OTP-Baustein für zustandsbehaftete Serverprozesse mit Nachrichtenbehandlung.","Eine rekursive Elixir-Funktion ruft sich auf einem kleineren Problem erneut auf und braucht einen Basisfall.","Mit = prüft Elixir, ob ein Wert zu einem Muster passt. Eine unpassende Bindung löst einen MatchError aus."],"correct":1,"explanation":"Eine rekursive Elixir-Funktion ruft sich auf einem kleineren Problem erneut auf und braucht einen Basisfall."},"q2":{"question":"Was zeigt das Beispiel zu „Rekursion“?","options":["Das Modul kann danach passende Callback-Funktionen implementieren.","wert erhält 3, weil die Tupelform passt.","Die Liste wird elementweise bis zum leeren Fall abgebaut."],"correct":2,"explanation":"Die Liste wird elementweise bis zum leeren Fall abgebaut."}},{"course":"elixir","ordinal":11,"title":"GenServer","theory":"GenServer ist ein OTP-Baustein für zustandsbehaftete Serverprozesse mit Nachrichtenbehandlung.","example":"use GenServer","example_note":"Das Modul kann danach passende Callback-Funktionen implementieren.","task":"Beschreibe einen Zähler als GenServer.","q1":{"question":"Welche Aussage erklärt „GenServer“ richtig?","options":["ExUnit stellt Testfälle und Assertions für Elixir bereit.","Elixir-Daten sind unveränderlich. Eine erneute Bindung mit demselben Namen erzeugt einen neuen Bezug auf einen Wert.","GenServer ist ein OTP-Baustein für zustandsbehaftete Serverprozesse mit Nachrichtenbehandlung."],"correct":2,"explanation":"GenServer ist ein OTP-Bauste